(function(root){
 'use strict';let loading;
 const config=()=>root.TenTaclesMapsConfig||{};
 function normalizeFix(fix){const coords=fix&&fix.coords||fix;const latitude=coords?.latitude,longitude=coords?.longitude,accuracy=coords?.accuracy,timestamp=fix?.timestamp;if(!Number.isFinite(latitude)||latitude< -90||latitude>90||!Number.isFinite(longitude)||longitude< -180||longitude>180||!Number.isFinite(accuracy)||accuracy<0||!Number.isFinite(timestamp)||timestamp<=0)throw new Error('Invalid GPS reading.');return {latitude,longitude,accuracy,timestamp}}
 function stale(fix,now=Date.now()){return now-fix.timestamp>60000||fix.timestamp>now+10000}
 function load(){if(!config().browserApiKey)return Promise.reject(new Error('Google Maps key is not configured.'));if(root.google?.maps?.importLibrary)return Promise.resolve();if(loading)return loading;loading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://maps.googleapis.com/maps/api/js?'+new URLSearchParams({key:config().browserApiKey,v:'weekly',loading:'async',callback:'tenTaclesMapReady'});s.async=true;let done=false;const fail=()=>{if(done)return;done=true;clearTimeout(timer);s.remove();delete root.tenTaclesMapReady;loading=null;reject(new Error('Hindi ma-load ang Google Maps. Check key, API access, billing at connection.'))};const timer=setTimeout(fail,15000);root.tenTaclesMapReady=()=>{if(done)return;done=true;clearTimeout(timer);delete root.tenTaclesMapReady;resolve()};s.onerror=fail;document.head.append(s)});return loading}
 // Adapter only. Call after an authenticated backend authorizes the customer's order.
 // This demo never calls it with real rider data and never requests location permission.
 async function mount({container,fix,statusElement}){const point=normalizeFix(fix);await load();const {Map,Circle}=await root.google.maps.importLibrary('maps'),{AdvancedMarkerElement}=await root.google.maps.importLibrary('marker');const position={lat:point.latitude,lng:point.longitude};const map=new Map(container,{center:position,zoom:16,mapId:config().mapId||'DEMO_MAP_ID',streetViewControl:false,mapTypeControl:false});const marker=new AdvancedMarkerElement({map,position,title:'Rider location'});const circle=new Circle({map,center:position,radius:point.accuracy,strokeColor:'#59278a',fillColor:'#59278a',fillOpacity:.1,strokeWeight:1});let latest=point;const status=()=>{if(statusElement)statusElement.textContent=(stale(latest)?'Last known location · hindi live':'Latest GPS reading')+' · accuracy ±'+Math.round(latest.accuracy)+' m · '+new Date(latest.timestamp).toLocaleTimeString('en-PH')};status();const interval=setInterval(status,10000);return {update(next){latest=normalizeFix(next);const p={lat:latest.latitude,lng:latest.longitude};marker.position=p;circle.setCenter(p);circle.setRadius(latest.accuracy);status()},destroy(){clearInterval(interval);marker.map=null;circle.setMap(null);container.replaceChildren()}}}
 // Wire to a rider's explicit Start sharing button after secure backend work.
 // Call stop on logout, trip completion, permission loss, and leaving the rider screen.
 function createGpsTracker({onPosition,onError}){let watch=null;return {start(){if(watch!==null)return;if(!root.isSecureContext||!root.navigator?.geolocation){onError(new Error('GPS needs HTTPS and a supported browser.'));return}watch=root.navigator.geolocation.watchPosition(p=>{try{onPosition(normalizeFix(p))}catch(e){onError(e)}},e=>{if(e.code===1)this.stop();onError(new Error(e.code===1?'Location permission denied.':e.code===3?'GPS timed out.':'GPS reading unavailable.'))},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})},stop(){if(watch!==null){root.navigator.geolocation.clearWatch(watch);watch=null}}}}
 function bind(parent){parent.querySelectorAll('[data-map-setup]').forEach(b=>b.onclick=()=>{const info=document.getElementById('detailsDialog');info.showModal();const section=info.querySelector('#mapsSetupNotes');if(!section){const n=document.createElement('section');n.id='mapsSetupNotes';n.innerHTML='<h3>Google Maps setup</h3><p>1. Google Cloud project + production billing.<br>2. Enable Maps JavaScript API.<br>3. Restrict the browser key to this website and Maps JavaScript API.<br>4. Add secure rider accounts + shared GPS storage before enabling tracking.</p><p>Hindi Google Maps ang kumukuha ng GPS — galing ito sa rider’s phone, with permission. No location is collected in this demo.</p>';info.append(n)}info.querySelector('#mapsSetupNotes').scrollIntoView({block:'nearest'})})}
 const api={normalizeFix,stale,mount,createGpsTracker,bind};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.TenTaclesMaps=api;
})(typeof globalThis!=='undefined'?globalThis:this);
